            <div
              style={{
                borderLeft: '1px solid #1e293b',
                background: '#0f172a',
                display: 'flex',
                flexDirection: 'column',
                height: '100%',
                overflow: 'hidden',
              }}
            >
              <div
                style={{
                  display: 'flex',
                  borderBottom: '1px solid #1e293b',
                  background: '#0b111e',
                  overflowX: 'auto',
                }}
