                cursor: 'pointer',
              }}
            >
              <div style={{ fontSize: 13, fontWeight: 700, color: '#f8fafc' }}>{stem.label}</div>
              <div style={{ fontSize: 10, color: '#94a3b8', marginTop: 4 }}>
                ID: {stem.id} | Unlocks at Stage S{stem.stage}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

