            }}
          >
            Tier 1: Quick Polish
          </button>
          <button
            onClick={() => setTier('tier2')}
            style={{
              padding: '4px 10px',
              fontSize: 11,
              fontWeight: 600,
              borderRadius: 4,
              border: 'none',
              background: tier === 'tier2' ? '#0284c7' : 'transparent',
              color: tier === 'tier2' ? '#fff' : '#94a3b8',
              cursor: 'pointer',
            }}
          >
            Tier 2: Layer Stack
          </button>
        </div>
      </div>

