            background: state.slotAssignScope === 'part-override' ? 'rgba(56, 189, 248, 0.16)' : '#111827',
            color: '#e2e8f0',
            cursor: 'pointer',
          }}
        >
          Override Selected Part Only
        </button>
      </div>

      {/* Tier 1: Curated Swatches with Non-Destructive Hover Try-On (Q4) */}
