          }}
        >
          🧼 Apply Solvent / Strip Overrides to Factory Clean
        </button>
      </div>

      {/* Tier 2: Full Layer Stack & [M] Mask B&W Diagnostic Mode */}
      {tier === 'tier2' && (
        <div
          style={{
            background: '#111827',
            border: '1px solid #1e293b',
            borderRadius: 8,
            padding: 12,
            display: 'flex',
            flexDirection: 'column',
