              Layer Stack ({activeMatSpec.layers.length} Layers) &amp; [M] Mask B&amp;W
            </span>
            {state.viewportMode === 'mask-bw' && (
              <button
                onClick={() => store.setViewportMode('lit', null)}
                style={{
                  fontSize: 10,
                  padding: '2px 8px',
