          >
            Close
          </button>
          <button
            onClick={handleDownloadPng}
            style={{ padding: '7px 16px', borderRadius: 6, background: '#9333ea', border: 'none', color: '#fff', fontWeight: 700, cursor: 'pointer' }}
          >
            ⬇ Download Spore Card (.png)
          </button>
        </div>
      </div>
    </div>
  );
};

